DROP TABLE IF EXISTS `jnqk_mailpoet_newsletters`;
CREATE TABLE `jnqk_mailpoet_newsletters` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `hash` varchar(150) COLLATE utf8mb4_unicode_520_ci DEFAULT NULL,
